window.CHAPTER_DATA["ch23"]={"id": "ch23", "num": 23, "part": "רשויות", "title": "סוגיא דרוחב מיעוט (ד:)", "paras": [{"s": "h2", "h": "\u003csup class=\"cb\" data-c=\"1052\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">1\u003c/sup>\u003cspan class=\"ca\" data-c=\"1052\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">סוגיא דרוחב מיעוט (ד:)\u003c/span>"}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1053\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">2\u003c/sup>\u003cspan class=\"ca\" data-c=\"1053\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">א. בירור בדברי הגמ' ופרש\"י\u003c/span>"}, {"s": "p", "h": "גמ'. היה גבוה מעשרים אמה ובא למעטו כמה ממעט, כמה ממעט, כמה דצריך ליה, אלא רחבו בכמה. רב יוסף אמר טפח, אביי אמר ארבעה. לימא בהא קא מיפלגי, דמאן דאמר טפח קסבר מותר להשתמש תחת הקורה, ומ''ד ארבעה קסבר אסור להשתמש תחת הקורה. לא, דכולי עלמא קסברי מותר להשתמש תחת הקורה, ובהא קא מיפלגי, מר סבר קורה משום היכר, ומר סבר קורה משום מחיצה. ואיבעית אימא דכולי עלמא קורה משום היכר, והכא בהיכר של מטה ובהיכר של מעלה קא מיפלגי, דמר סבר אמרינן היכר של מטה כהיכר של מעלה, ומר סבר לא אמרינן היכר של מטה כהיכר של מעלה. ואיבעית אימא דכולי עלמא אמרינן היכר של מטה כהיכר של מעלה, והכא בגזירה שמא יפחות קמיפלגי. ע\"כ."}, {"s": "h7", "h": "בסתירת דברי רש\"י בהאי היכר דבעינן – אי הוה בעמידה ובשימוש או בכניסה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1054\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">3\u003c/sup>\u003csup class=\"cb\" data-c=\"411\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">4\u003c/sup>\u003cspan class=\"ca\" data-c=\"1054 411\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">והנה צ\"ב באוקימתא דכ\"ע קסברי מותר להשתמש תחת הקורה וקמיפלגי בקורה אי הוי משום היכר או משום מחיצה, וכתב ברש\"י בטעמא דמ\"ד משום היכר סגי ליה בטפח, דהרי יש כאן היכר בכניסתן כשמשתמשין תחת הקורה, ובדקדוק לשונו צ\"ב מש\"כ בכניסתן כשמשתמשין דלכאורה בכניסתן משמע בדרך הילוכם כשנכנסים (וכדאמרו בגמ' לעיל בחילוק סוכה ממבוי דסוכה לישיבה עבידא ומבוי להילוך עביד), ומשתמשין משמע בהיותם שוהים בתוך המבוי, וכן דלעיל באוקימתא דמ\"ד טפח ס\"ל מותר להשתמש כתב דיש היכר לעומד תחת הקורה. ועמידה, הילוך ושימוש לאו היינו הך (ע' שבת ק. בחילוק הילוך מתשמיש דע\"י הדחק. גם יש לשמוע מגמ' לעיל (ג.) גבי חילוק ישיבה מהילוך, דעמידה יש לדמותה לישיבה יותר מלהילוך (עפרש\"י שם)).\u003c/span>"}, {"s": "h7", "h": "בירור במשמעות היכר מלתחת הקורה – הא לא אשכחן להכירא אלא מלגיו או לבר"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"412\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">5\u003c/sup>\u003cspan class=\"ca\" data-c=\"412\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ועוד קשה מה שנקט היכר לתחת הקורה, ולקמן (ח:) אמרה הגמ' באוקימתא דבין למ\"ד מותר להשתמש ובין למ\"ד אסור כ\"ע סברי קורה משום היכר ופליגי אי הכירא מלבר אי מלגיו, אבל הכירא מלתחת לא אשכחן למ\"ד. ועוד דהכא משמע דנידון אי איתא להכירא אי לאו, תלוי באי שרי להשתמש, והתם משמע ליהפך, דנידון אי שרי לאישמושי תליא באי איתא להכירא.\u003c/span>"}, {"s": "h7", "h": "בגדר תיקון דטפח תחת הקורה - דמשמע דבעינן לכ\"ע וחשיב אחד מד\"ט"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1055\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">6\u003c/sup>\u003csup class=\"cb\" data-c=\"413\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">7\u003c/sup>\u003cspan class=\"ca\" data-c=\"1055 413\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ועוד יש להקשות אמה דכתב דמ\"ד אסור להשתמש, והיינו משום דחודו הפנימי יורד וסותם, בעי ד\"ט, דכיון דאפיקתיה מתחת הקורה צריך שיהיה מקום הניכר וחשוב, דלא נתבאר למה לא די שיעשה הטפח מלגיו, דכיון דלא נחתינן השתא לדין דהיכר של מטה, הרי שאין למצוא טעם בשיעור מקום שממנו יש היכר (וביחוד דמשמע דלמ\"ד קורה משום מחיצה ליתא לעניין היכר של מטה כלל, ולא מצי למיתלי בהכי, דאל\"ה הוי ליה לאוקמי פלוגתייהו בהכי (דכ\"ע קורה משום מחיצה ופליגי באי אמרינן היכר של וכו')), ומשמע דהא דבעינן מיעוט תחת הקורה הוא לכ\"ע, ואף אי חודו הפנימי יורד וסותם, ואף אי נימא דהכירא מלגיו, ומיעוט דתחת הקורה מהני לעניין מסויים לכ\"ע בשווה (וכן מבואר ברש\"י דכתב וז\"ל ולמשתמשים במבוי אין להם היכר במבוי שהרי בנמוך הן הלכך צריך שימשך וכו'. ע\"כ. והיינו, דנקט טעמא דמ\"ד ד\"ט בהא דלא מהני מיעוט טפח, וצ\"ב למה לא ביאר בפשטות טעמא דהאי מ\"ד בד\"ט, ומשמע דאף להאי מ\"ד ד\"ט מהני טפח לאיזה עניין, רק דלגבי הכירא דהמשתמשים במבוי צריך שימשך האי מיעוט טפח לתוך המבוי), וצ\"ב מהו עניין זה, ואי איתא, אף אי אסור להשתמש, אמאי לא די בו לבד. ועוד צ\"ב דבפשטות משמע דלמ\"ד ד\"ט הוה טפח אחד מהם תחת הקורה, וקשה דאי בעינן ד\"ט משום שיהא מקום הניכר וחשוב ודשרי לאישתמושי ביה, היכי מהני האי טפח לאיצטרופי אחר דאסור להשתמש בו.\u003c/span>"}, {"s": "h7", "h": "דקדוק לישנא דרש\"י בפ' כיון דאפיקתיה וכו' – הא דשינה פירושו בתרי לישני דגמ'"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"414\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">8\u003c/sup>\u003cspan class=\"ca\" data-c=\"414\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">והדק היטיב מה דשינה לשונו הטה' הכא מדלקמן (ד\"ה גזירה) בחשש דשמא יפחות, דהתם כתב בטעמא דבעינן לשיעור ד\"ט (אף דהיה אפשר לאפוקי מחששא בפחות מכן), וז\"ל וכיון דאפיקתיה מהיכר של מעלה אוקמיה אארבעה דחשיבי בכל דוכתא. ע\"כ. ולשון זו משמע דאין למצוא חשיבות בד' ביחס לחששא דשמא יפחות, רק דכיון דבעינן דליהווי ביותר מטפח, הרי דשיעור חשוב שמצאנו היותר מטפח הוא ד\"ט (ואמנם עדיין יש לדקדק מה שנקט דאפיקתיה מהיכר של מעלה ולא כתב סתם דאפיקתיה מטפח. וצ\"ע). אבל הכא כתב דצריך שיהא מקום הניכר וחשוב, ומשמע דהוא מגדרי היכר המדובר, ופירוש לפירושו דכיון דאפיקתיה מתחת הקורה, היינו, דלא נוכל למצוא תועלת היכר שימוש, במיעוט הממעט תחת הקורה, לא יהני מיעוט במשך טפח במקום המותר לשימוש, דהאי שיעור טפח לא מהני להיכר שימוש אלא משום שהוא תחת הקורה, אבל אי אפיקתיה מתחת הקורה ותרצה להכין מקום אחר, צריך שיהיה זה המקום בשיעור הנובע מגדרי חשיבות מקום, והיינו ד\"ט. כך נראה לכאורה. וצ\"ב תועלת מה דהוי מקום שימוש בתחת הקורה לגבי שיעור מקום.\u003c/span>"}, {"s": "h7", "h": "בירור מ\"ד היכר של מטה כשלמעלה – בגדר היכר של מטה ושיעורו בד\"ט"}, {"s": "p", "h": "ועוד צ\"ב פשטות הגמ' באוקימתא דכ\"ע ס\"ל קורה משום היכר ופליגי באי אמרינן היכר של מטה כהיכר של מעלה, ולא נתבאר היטיב, דהיכר של מטה מאן דכר שמיה, הלא אין פסול דלמעלה מכ' אלא רק משום גובה הקורה, ואין גובה הקורה אלא בהפרשו מקרקע המבוי, ואין זה שני דברים. וגם צ\"ב מה דלא אשכחן בשום דוכתא עניין זה דהיכר של מטה כלל, ובמבוי שמתחילתו נמוך מכ' אמה היכר של מטה איה הוא, ואלא שתאמר דבמבוי נמוך מכ' כל המבוי חשוב היכר של מטה, א\"כ הרי זה דין במבוי והוי ליה למיתלי שיעור היכר של מטה בשיעור מבוי, וכדלקמיה בחקק. וגם צ\"ב מה דלמ\"ד לא אמרינן היכר של וכו' לא נתבאר פשר שיעור ד\"ט, דהא לעיל דבעינן למימר דפליגי בקורה אי משום היכר אי משום מחיצה, ניחא לן במה דמ\"ד משום היכר סגי ליה בטפח, וא\"כ הול\"ל טעמא דמ\"ד ד\"ט, וגם ברש\"י לא פירש. ויותר מהכל צ\"ב מה מהני מיעוט ד\"ט לענין היכר של מטה אחר שאין ראוי לקורתו מיעוט כיון שאין הוא ממעט דבר, דחלל שעליו עולה עד הרקיע."}, {"s": "p", "h": "עוד צ\"ב למה לא פירשו (גמ' ורש\"י) דלאוקימתא קמא כ\"ע קסברי קורה משום מחיצה, וגם צ\"ב למה לא נקטו סדר דבמאי פליגי כנקטו התם (ח:), היינו, דבתחילה יעמידו מח' באי קורה משום היכר או משום מחיצה, ואחר כן וכו' כדלקמן."}, {"s": "h7", "h": "בתי' תוס' דאף למ\"ד משום מחיצה לא בעינן לד\"ט – בהא דדימו להא דכ' רש\"י לק' דאיתיה לדופן"}, {"s": "p", "h": "והנה בתוס' הכריחו פירוש רש\"י להעמיד מח' אי מותר להשתמש אליבא דמ\"ד קורה משום מחיצה, ואמרו דאין להקשות א\"כ מ\"ט דמ\"ד טפח, הא אמרו לקמן דאי קורה משום מחיצה בעינן ד\"ט, ופרש\"י דהוא משום אין מחיצה לפחות מד', וכתבו בתוס' דאין לחוש ע\"פ מה דכתב ברש\"י לקמן דהכא איתא לדופן, והנה ברש\"י לקמן משמע דעיקר חילוקו דבפחות מי' אין מבוי לקורה, והיינו, דהכא אין החסרון אלא בקורה לבד, ולא במה שהקורה אינה עומדת במבוי (היינו, בשיעורו דגובה י\"ט ואורך דמבוי כל חד לשיטתו), וא\"כ עדיין יקשה דלא יהני האי סברא לבאר אמאי לא בעינן הכא ד\"ט הנצרכים לקורה לבד אי הוה משום מחיצה."}, {"s": "p", "h": "וכבר הקשו אתוס' מה דלא אתי לה אלא משום מ\"ד טפח, ולדברי רש\"י לקמן דהא דלמ\"ד קורה משום מחיצה מהני מיעוט ד\"ט הוא רק אי אמרינן דחודה החיצון יורד וסותם, וע\"י מיעוט ד\"ט הוי מחיצה העשויה לד\"ט, אבל לאוקימתא דהכא הרי דמ\"ד ד\"ט סבר דחודה הפנימי יורד וסותם, ולא יהני ד\"ט הללו דחד מינייהו הוי מאחרי המחיצה."}, {"s": "h7", "h": "בד' רש\"י דמשמע לק' דטעמא אי מותר להשתמש תליא באיזה חוד יורד וכו'"}, {"s": "p", "h": "וברש\"י גופא כתב במקורו דטעמא דמ\"ד מותר להשתמש הוא משום דאמר חודו החיצון וכו' כדמשמע לקמן, והמציינים ציינו לדף ח ע\"ב, ולא נתבאר איך משמע כן, אי לאו בהצטרף דברי תוס' דהוכרח כן מהא דלא נחתו דכ\"ע ס\"ל דקורה משום היכר (וכן דפליגי באי הוה משום היכר או משום מחיצה דאיתא להאי אוקימתא, וכן דלהאי אוקימתא כ\"ע סברי מותר להשתמש), אלא דא\"כ אין לומר בזה כדמשמע לקמן."}, {"s": "h7", "h": "באיזה היכר אמרו בשל מטה – ומאיזה מקום בעינן שיהא ניכר"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"415\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">9\u003c/sup>\u003cspan class=\"ca\" data-c=\"415\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">והנה בפשטות משמעות היכר של מטה כמש\"כ לעיל הוא שיעור המקום הנצרך שבהיות בו תהיה הקורה ניכרת, היינו, דמלבד מה דבעינן שיהא ניכר שיש קורה למבוי, וזה במה שיש לראות המבוי עם הקורה (ומה דבזה מהני לחלק מבוי זה משאר רה\"ר), יש לדון מאיזה מקום בעינן שיהא ניכר, וזה צ\"ב בתרתי, חדא, דלכאורה בהא גופא פליגי (לחד אוקימתא) לקמן, אי היכרא מלבר או מלגיו, ועוד דאף אם נשמע איזה טעם בהיכר של מטה דהוא בדווקא ביחס לגובה כ' אמה, ושהוא ותיקונו חלוק מגדר היכר קורה סתם, עדיין יקשה דלמ\"ד הכירא מלבר מה מהני שום תיקון שבתוך מבוי, אחר דלגבי בני רה\"ר הוי גבוה כ' אמה, ולא שלטא ביה עינא.\u003c/span>"}, {"s": "h7", "h": "במה דלכ\"ע לא בעינן היכר קורה בכל המבוי"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"416\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">10\u003c/sup>\u003cspan class=\"ca\" data-c=\"416\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">עוד צ\"ב מה דמכוליה סוגיא משמע דעכ\"פ לא בעינן שיהא שימוש כל המבוי ניכר שהוא שימוש תוך כדי היכר קורה, והנה מאחר דסיבת תקנת לו\"ק הוא משום חששא דאתי לאחלופי, א\"כ מה מהני היכר דמקומות הנ\"ל לבד, הא בהיות שאר מקומות שאין תקנת לו\"ק ניכרת בהם, עדיין איתא לחששא דאתו לאחלופי.\u003c/span>"}, {"s": "h7", "h": "בהא דאוקמוה לחשש דשמא יפחות בדכ\"ע משום היכר"}, {"s": "p", "h": "עוד צ\"ב מה דאוקמוה לפלוגתא דאי חיישינן לשמא יפחות אי לאו, אי בעית אימא כ\"ע קורה משום היכר, דלכאורה האי חששא איכא למיחש אף למ\"ד קורה משום מחיצה ומותר להשתמש תחת הקורה, וביותר מה דאיכא למידק דנחתו לאוקמיה אצד דלכ\"ע אמרי' היכר של מטה כהיכר של מעלה, ולכאורה אין שייכות במאי הוה טעמא דבעינן טפח או דסגי בטפח, לחששא דשמא יפחות. ואמנם זה לא יקשה אלא בהצטרף קושיא קמא, דאי לא אמרי היכר של וכו', ליכא לאוקמי דהוה רק משום חששא למ\"ד קורה משום היכר."}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1056\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">11\u003c/sup>\u003cspan class=\"ca\" data-c=\"1056\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ב. בגדר מיעוט גובה קורה\u003c/span>"}, {"s": "h7", "h": "בביאור תמיהת הגמ' הכא כמה ממעט ולק' בכמה חוקק"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"417\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">12\u003c/sup>\u003cspan class=\"ca\" data-c=\"417\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">והנה יש להבין מה שדקדקה הגמ' הכא ובסוגיא דחקק לקמן (ה.) בלישנא דבעיא דכמה ממעט דתמהו מאי בעיא כמה ממעט הרי ממעט כמה דצריך לה, והיינו, דיש לשמוע מיניה דסברה הגמ' דגדר כמה ממעט, היינו, שנרצה לומר דגדר מיעוט ושיעורו אינו גדר עצמי, אלא ביחס לדבר אחר, ובעו כמה ממעט, היינו, ביחס למה הוי האי מיעוט, דנחשוב שיעורו בהתאם לכך, ואזה תמהו, דגדר האי מיעוט בשמו, פשיטא דהוא מיעוט המרובה, היינו, חלל, דתליא הפסול ברובו (בהרבה ממנו), ושיעור המיעוט הוא כמה דצריך ליה, ומשמע דהאי בעיא ליכא, דלישנא דנקטו אלא רחבו בכמה משמע דהוא תיקון הבעיא, והיינו, דגדר מיעוט עצמו ודאי אינו נמדד שלעצמו, היינו, שאם גובה המבוי עשרים ואחת אמה, ונמעטו בהגבהת הקרקע אמה, אין ביאור הדבר דגובה המבוי נפעל מן המיעוט שנחשוב אותו כגדר נפרד מן המיעוט, היינו, דגובה המבוי המשתער רק מגדיר שבאם נרצה לתקנו נצטרך למיעוט הנמדד לפי זה, אלא ביאורו שבהיות המיעוט ליכא לגובה מבוי, וגבהו הוא מה שיש מן המיעוט ולמעלה, וזה אמרו אלא רחבו בכמה, והיינו, כי ביחס למיעוט החלל, הרי מיעוט ברוחב כל דהוא חשוב מיעוט גמור ביחס לאותו הרוחב, ואם יהיה גדר רוחב המיעוט ביחס לחלל עצמו (היינו, כדבעינן למימר לגבי גובה המיעוט), הרי דבכל דהו כבר ליכא להאי חלל, ואי נימא דבעינן יותר רוחב, הרי בהכרח שאין זה גדר בחלל (היינו, במשמעותו האחידה בכל רוחבו, וזהו ברוחב שווה בכל החלל שיוגדר כחלל אחד), אלא הוא גדר ברוחב חלל, והיינו, דבכל דהו רוחב כבר חשיב חלל, ואי נימא דבעינן מיעוט חלל ברוחב מסויים, בהכרח דהאי דשיעור רוחב הנ\"ל בחלל אינו בגדרו כחלל (היינו, כדלעיל, ודוגמתו באהל טפח על טפח ברום טפח), אלא שיעור ברוחב איזה דבר, ודבעינן שיהיה החלל הנרצה קיים ברוחב מסויים.\u003c/span>"}, {"s": "h7", "h": "בירור בלשון רש\"י בתועלת הגבהת הקרקע – אי הוה גדר בגובה חלל או בהעדרו"}, {"s": "p", "h": "ואחר העיון נראה דכן יש לדקדק בשינוי לשון שכתב ברש\"י בתחילה (ד\"ה ובא) כתב דמה דעבידא הגבהת הקרקע היא למעט גובה החלל, ואח\"כ (ד\"ה כמה דצריך ליה) כתב דהמיעוט הנדרש הוא עד שלא יהא החלל יותר על עשרים, והיינו, דבתחילה יחס המיעוט לגובה החלל, וביחס לחלל שכאמור הוא בגדר אחד בעצמותו, הרי שלדבר בגובהו הוא כביכול שנרצה למצוא הרכבו הבסיסי באורך ורוחב וגובה, וליחס זה היה לו לומר אח\"כ במיעוט הנדרש שהוא עד שיהא גובה החלל עד עשרים, וצ\"ב מה ששינה לשונו לומר עד שלא יהא וכו'."}, {"s": "p", "h": "והנראה בזה דבא להדגיש תמיהת הגמ' דאמנם שביחס לעשיית המיעוט יש לשמוע שיעורו בגובה החלל, אבל ביחס להיות המיעוט די ושנמצא החלל ראוי הרי זה ודאי גדר בחלל עצמו, וביחס לחלל עצמו יהיה ריבוי הגובה או מיעוטו גדר עצמי והרי הוא או שאינו, והיינו, דנקט לישנא דשלא יהא החלל יותר, דביאורו שילא חלל כזה, דלעומת יחס גובה שהוא יחס מחלק לחלל המסויים (היינו, שנחשיב גובהו כנפרד מעצמותו, ושאפשר שיהיה גבוה כך או כך), יחס היות החלל כזה או כזה הוא ביחס שלילי, ובענין שלא יהא ואין זה כזה."}, {"s": "h7", "h": "ביאור שינוי לשון רש\"י לתרי מ\"ד - במשמעות מה דעבידא קורה לתיקון המבוי"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"418\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">13\u003c/sup>\u003cspan class=\"ca\" data-c=\"418\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ויש לדקדק שינוי לשון דכתב ברש\"י במשמעות מה דעבידא קורה לתיקון המבוי, דלמ\"ד קורה משום היכר כתב (ד\"ה לא דכולי עלמא) קורה שתיקנו חכמים למבוי משום וכו', ולעומת כן למ\"ד קורה משום מחיצה כתב (ד\"ה ומ\"ד ארבעה) קורה המתרת במבוי טעמא משום מחיצה. ומשמע דלמ\"ד משום מחיצה אין גדר קורה שהיא מתקנת חכ', והיינו, שהיות קורה דעבידא היכר הוא בגדר גזירת חכמים, דבלא הא דחיישנן דאתי לאחלופי לא בעינן להיכר וגם לא הוי היכר, אבל היות קורה דעבידא מחיצה אינו מגדרי עצם התקנה, ויותר היה לומר דלא חיישי רבנן דאתי לאחלופי אלא במבוי שאין לו קורה, דקורה עבדא מחיצה ובאיתא למחיצה ליתא לגזירה, ואזה שייך לישנא דנקט קורה המתרת, הויינו דכתב שם אח\"כ בגדר פסול דלמעלה מכ' דאמרו חכ' דבטפי מעשרים לא אמרינן יורד וסותם, והיינו דמאחר שיש לקורה דעבדא מחיצה להיות מתרת בלא תקנת חכ', וכיון דפסול טפי מכ' אינו פסול במחיצות, הרי דלא הוה שום פסול בטפי מעשרים ובהכרח דהוא מתקנת חכ', והיינו, דבעו להיכר דעבדא האי מחיצה, והם שאמרו דבטפי מכ' אינו יורד וסותם.\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"419\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">14\u003c/sup>\u003cspan class=\"ca\" data-c=\"419\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">וזה דכתב ברש\"י למ\"ד קורה משום היכר דהיכר בעלמא הוא דלא ליתי וכו', והיה להקשות דהא לכ\"ע הוא כדמשמע ברש\"י לעיל (ריש מסכתין), וכן דאחר תקנת חכ' לא מהני מחיצה סתם (ומ\"ד דמהניא בעי לק\"ו), וודאי דאף אי הוה משום מחיצה, בעינן למחיצה דאית היכר דלא ליתי וכו', אלא היינו כוונתו, דאי קורה משום היכר הרי דיש בקורה עצמה בהיות דבר היכר להועיל אחששא דלא ליתי וכו', אבל אי קורה משום מחיצה (אף דיש במחיצה זו היכר), אין ההיכר מקורה עצמה במשמעותה כמחיצה (והגע עצמך דהיאך מחיצה זו תהני דלא ליתי לאחלופי אחר דג' (או ד' כאמור) מחיצות גמורות לא אהנו), אלא עיקר ההיכר הוה במה דלא שרינן מבוי אלא בהיותה (במה שאין היא מצורת מבוי כלל או במשמעותו הדומה לרה\"ר).\u003c/span>"}, {"s": "h7", "h": "המתבאר לפי\"ז דברי רש\"י דנקט היכר אכניסה כשמשתמשים תחת הקורה"}, {"s": "p", "h": "ולפי\"ז נראה לבאר מה דכתב ברש\"י בהיכר שיש במיעוט טפח למ\"ד קורה משום היכר דיש כאן היכר בכניסתן כשמשתמשים תחת הקורה, והיינו, דמאחר דגדר היכר שיש בקורה הוא ביחס לחששא דאתי לאחלופי, ומאחר דהא דאתי לאחלופי הוא משום שימוש רבים שיש במבוי, היה לומר דבעינן שיהא ההיכר בכל המבוי שיש בו שימוש הנ\"ל, והיינו דכתב דבשימוש הניכר (כשמשתמשין תחת הקורה) יש משמעות היכר אכל המבוי, משום שהוא בכניסתן למבוי, וזה ביאור מה שלא הזכיר הא דמהני היות קורה שהיא בפתח המבוי בשאר סוגיא, דאף דלכ\"ע מהני האי קורה להיכר, אין משמעות מקומה משום היכר אלא משום מחיצה וכו'."}, {"s": "h7", "h": "הצ\"ב במה דתלה ר\"י שיעור ד\"ט דרה\"י בדבעינן שתהא המחיצה ראויה לד\"ט"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"420\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">15\u003c/sup>\u003cspan class=\"ca\" data-c=\"420\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">כתב ברש\"י באוקימתא דמ\"ד ד\"ט סבר קורה משום מחיצה, דהיינו, דבעינן שתהא המחיצה ראויה לד\"ט, דבלא כן לאו מחיצה היא, וכתב דהיינו טעמא דאין רשות היחיד פחות מד\"ט אף שמוקפת מחיצות עשרה, וזה קשה דלכאורה גדר שיעור ד\"ט ברה\"י הוא במקום שלה דבעינן שיהא מקום חשוב, והגע עצמך ברה\"י שיש לרבע בה ד\"ט אלא שהיא רחבה בצד אחד וצרה בצד שני כזה ומי איכא למימר דלאו רה\"י היא, ואי הוה דיש חסרון במחיצה עצמה מה שאין שאינה לד\"ט, הרי חלק מחיצה שבצידי אורכה של רשות אינם לד\"ט מרובים, מי נימא דלאו רה\"י היא, אלא ודאי שאין חסרון דד\"ט במחיצה עצמה, אלא הוי חסרון במקום דלא חשיב בפחות מדע\"ד טפחים, וכן פרש\"י בכמה מקומות, ומאחר דהוי חסרון במקום, הרי דכל המחיצות יחד בגדר אחד, והוו כולן מחיצות הראויות וכו', וא\"כ אינו ענין להכא דליכא לחסרון מקום דע\"ד אלא מצד אחד וביחס למחיצה הנעשית ע\"י קורה. ואמנם דעיקר ביאור שכתב בסברת מיעוט ד\"ט שפיר, דיש לשמוע דבעינן שיהא למחיצת קורה מקום ד\"ט לעצמה ולעניין גובה דעד כ', אבל מה שתלה בזה דין ד\"ט דרה\"י קשה. \u003c/span>"}, {"s": "h7", "h": "בראיה שהביא רש\"י מגזוזטראות דחנניה בן עקביא"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"421\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">16\u003c/sup>\u003cspan class=\"ca\" data-c=\"421\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">עוד יש לדקדק דהרי כמש\"כ ברש\"י דין שיעור מקום דרה\"י דהוה בד\"ט מפורש בכמה מקומות, וא\"כ מהו שהביא הא דגזוזטראות דחנניה בן עקביא, כיהודה ועוד לקרא, והנה עצם מה שהביא דין גזוזטראות דחנניה בן עקביא לא קשיא דאכן יש לדמות זה לענייננו, דהא התם נמי איירי בגוונא דליכא מחיצות ממש, אלא דבעינן למימר דכוף קרקע גזוזטרא סביב הנקב דליהוו לה מחיצות, ודמי להכא דבעינן למימר חוד קורה יורד וסותם, ואיכא ראיה דאף באופן דאחר שנאמר כוף או יורד וסותם יהא המחיצה ראויה למקום ד\"ט (הכא בשאר מבוי, והתם בגזוזטרא עצמה דאף דאמרינן כוף הא איכא למקום דע\"ד) לא מהני, ובעינן שיהא מקום דע\"ד קודם שנאמר דליהוו מחיצות, וזה ליתא למישמע מדין ד\"ט דרה\"י, וזהו דכתב בתחילת הדיבור דביותר מכ' לא אמרינן יורד וסותם, היינו, דאי הוה יורד וסותם, וטעמא דיותר מכ' הוי מטעמא אחרינא (היכר וכו'), וצ\"ב.\u003c/span>"}, {"s": "h7", "h": "ביאור הא דלכ\"ע בעינן מיעוט תחת הקורה - גדר חוד ופי ופני דבר האמורים מכחו ושיעורו"}, {"s": "p", "h": "והנה בהקדם דבר הברור דלכ\"ע, היינו, בין למ\"ד דחודה הפנימי או החיצוני יורד וכו', הא פשיטא דאין משמעות בהאי חוד, איזה שיהיה, אי לאו משום דהוי חוד דרוחב קורה טפח, וכן דהאי לא שניא אי נימא היכרא מלגיו או מלבר (דמשמע דההיכר הוא פני הקורה), בלא דהאי הכירא הוא מקורה דרחבה טפח (וכדאיתא בקורות המתאימות, דבעינן דלהווי כולהו בתוך כ', ולא פלגינן באי מלבר להכשיר אי קורה דמלבר תוך כ' וכו'), וכן  הוא בכל מקום שנקטו חלק דבר שהוא מהיות חלק הדבר השלם (כמו פי תקרה וכו')."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"422\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">17\u003c/sup>\u003cspan class=\"ca\" data-c=\"422\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">וע\"כ בכל מיעוט שנבוא למעט ברור הוא דעכ\"פ ניבעי דיהא מיעוט תחת כל רוחב הקורה, היינו, טפח, ודאי לאו הכי ליכא לקורה ולחודה דנימא ביה שירד ויסתום, וכן דבלא כן ליכא להיכרא דפני הקורה, דאף דיהני להכירא אין זה הכירא דקורה (היינו, בכל דיניה, רוחבה, ובריאותה, וכו'). ומיניה לגדר תיקון נפרד שיש במיעוט דתחת הקורה לבד, והיינו, דביחס לפסול דקורה למעלה מכ', הם כ' אמה הנמדדים בחלל מבוי, די בדעביד מיעוט תחתיה לכל רחבה, דלהווי חשיב דליכא לחלל כ', ודאיתא לקורה במקומה. \u003c/span>"}, {"s": "h7", "h": "ביאור מה דלכ\"ע לא בעינן היכר בכל המבוי – גדר חשיבות שיש בפתח דמבוי אכל מבוי"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"423\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">18\u003c/sup>\u003cspan class=\"ca\" data-c=\"423\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">וזהו גם טעם מה דלכ\"ע תיקון המועט מהני (היינו, דאי בעינן היכר בשימוש, לא בעינן שיהא ההיכר בכל מקום שימוש, אלא סגי בקצת מקום שימוש וכו'), ודלא בעינן שיהא מיעוט בכל אורך (או בהכשר) המבוי, והיינו, דמאחר דאיתא למיעוט תחת הקורה, כבר איכא לקורה, והרי אין תיקון קורה אלא אפתח מבוי, היינו, דאף שיש בהנחת קורה גדר תיקון אכל אמבוי, אין זה משום שיש להאי טפח חשיבות או יכולת השפעה בכל אורך המבוי, אלא משום חשיבות שיש בפתח דמבוי (במשמעותו העצמית, וקודם תיקון קורה) אכל מבוי, וע\"כ אין תיקון דקורה חשוב בכל המבוי, אלא רק במקומה, והא דמהני בכל המבוי הוא משום חשיבות המקום ולא חשיבות התיקון.\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1057\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">19\u003c/sup>\u003cspan class=\"ca\" data-c=\"1057\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">אלא דמאחר דהאי קורה לאו לתיקוניה מחיצות המבוי, ומשמעותה אפתח אינו ביחס לגידור המבוי, אלא במה שיש להועיל ביחס להגדרת מקום שימושו, ולהבחנת שימוש בו משימוש ברה\"ר, וביחס לשיעור כ' דהוא משום הכירא, יהא גדרו בשימוש דקרקע, היינו, דבעינן דיהני האי טפח להיכר ביחס למשמעותו כקרקע היא מקום שימוש. ולזה לא יהני מה דיש לרואה לראות החלל דבין קרקע לקורה, דאין בגדר חלל הנ\"ל משמעות שימוש.\u003c/span>"}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1058\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">20\u003c/sup>\u003cspan class=\"ca\" data-c=\"1058\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ג. בגדר דין גובה מבוי\u003c/span>"}, {"s": "h7", "h": "בירור בגדר דין גובה מבוי ובחלקיו – גדר משותף לדינים שהם בשייכות שני דברים"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1059\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">21\u003c/sup>\u003csup class=\"cb\" data-c=\"424\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">22\u003c/sup>\u003cspan class=\"ca\" data-c=\"1059 424\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">וביאור זה צריך להקדמה, דהנה דין גובה מבוי הוא דין בשייכות שני דברים, היינו, קרקע, קורה, וגובה חלל כ' המשייכם, וכל דין שהוא בשייכות שני דברים יש למצוא גדרו בשלושה פנים, או בדבר אחד מן הדברים או במשייכם זה לזה, ובענייננו שיש למצוא דין גובה מבוי עד כ', או בקרקע. או בקורה, או במשייכם, היינו, גובה חלל עד כ', והנה עכ\"פ שנאמר יהיה גדר גובה האמור בחלל, וכדאיתא בגמ' דגובה חלל תנן (ר\"ל דאף אי נימא דהוא דין בקרקע יהיה גדר גובה כ' בחלל המשוייך לקרקע, ולא בריחוק קורה מקרקע). וכשתימצי לומר יהיה חילוק דעל איזה מאלו מוסב הדין האמור גם חילוק גדר הדין עצמו. \u003c/span>"}, {"s": "h7", "h": "משמעות גדר דין גובה מבוי אי נימא דהוה דין בקרקע ובחסרון דיותר מכ'"}, {"s": "p", "h": "והנה אי הוה דין בקרקע, יהיה גדרו הדין דבעינן דלהווי קורה עליה, ויהיה שיעור הגובה בכדי שיש לקורה להיחשב עליו דמבוי. ובאופן הפסול, היינו, יותר מכ', יש למצוא שני חסרונות, או בחלל קרקע, או בהיכר קרקע."}, {"s": "p", "h": "חלל קרקע, היינו, דאין לקרקע להחשיב חלל כעליה (שלה) אלא עד עשרים (ודוגמת מה דרה\"ר תופסת אווירה עד י\"ט, ואין להקשות מה שייך לומר במבוי שכתליו גובים יותר מכ', שאין חשוב אווירו אלא עד כ', דהאי אוויר האמור אינו במבוי כמקום, אלא בקרקע, ומה שעליה (ודכתב רש\"י לקמן (ה. ד\"ה רב יוסף), דבלמעלה מכ' חשיב איתיה לדופן, והיינו, דאין זה חסרון בקורה דאינה ע\"ג מבוי)), ויהיה טעם הפסול ביותר מכ' דאין הקורה על אוויר הקרקע."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1060\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">23\u003c/sup>\u003cspan class=\"ca\" data-c=\"1060\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">היכר קרקע, היינו, דאין היכר קרקע אלא עד עשרים, ואנן בעינן שתהא הקורה תוך היכר של קרקע, היינו, דיש לרואה לראות בקורה כנותנת משמעות בקרקע, רק אם היא בתוך מקום שיש לרואה קרקע לתור אחר דברים השייכים לה, ושראייתם חשובה ראיה אחת עם קרקע שראה (ולפי\"ז יבואר מה דלא מהני היכר דהמביט מרחוק דדרך שרואה אף בדברים הגבוהים, והיינו טעמא, דבריחוק אין חשוב היכר של קרקע (היינו, שנחשוב דהאי קרקע אית לה קורה, דלגבי המביט מרחוק הוה כשני דברים בעלמא, ואנן בעינן שיהא ניכרת קרקע במשמעותה כעיקרית, וקורה עליה כמשמעות בה, ולא שני דברים במשמעותם הנפרדת ובחיבור דקרבה) דאף ראייתו את הקרקע אינו במשמעותה וחשיבותה, וכדאיתא למי מי שעומד בקירוב לה).\u003c/span>"}, {"s": "h7", "h": "משמעות גדר דין גובה מבוי אי נימא דהוה דין בקורה ובחסרון דיותר מכ'"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"425\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">24\u003c/sup>\u003cspan class=\"ca\" data-c=\"425\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">ואי הוה דין בקורה יהיה גדרו דלענין קורה עצמה ומה שיש לה לפעול בעינן שיהיה תחתיה קרקע, ושיעור הגובה הוא במה שיש לקרקע להיחשב תחתיו דקורה, ובאופן הפסול, היינו, יותר מכ', יש למצוא שני חסרונות, והן היפך מה שאמרנו בקרקע, היינו, או דאין חשוב תחתיו דקורה אלא עד עשרים (ודמיא לדין עשרים דסוכה לר\"ז דעד עשרים אמה אדם יושב בצל וכו') וטעם הפסול דאין הקרקע נתונה להשפעת הקורה, או דפסולו משום שאין הקרקע תוך היכר של קורה, היינו, דיש לרואה לראות פעולה שיש בכח קורה לפעול רק בדברים שנמצאים תוך היכר של קורה וכו' כהנ\"ל.\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1061\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">25\u003c/sup>\u003cspan class=\"ca\" data-c=\"1061\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ותראה חילוק שני פנים אלו, שהוא נובע מהבדל שבעצם משמעות קורה מקרקע, היינו, דאי איתא לגדר קורה שלעצמה, פירושו, שקורה לבד יש בה משמעות לפעול, ואין היא צריכה למקום שתחתיה להיות משמעות זו, ואי איתא לגדר קרקע שלעצמה, פירושו, שבקרקע לבד יש משמעות להיות נפעלת ואין היא צריכה לקורה שעליה להיות בה משמעות זו. ומשמעות האמורה בקורה, היינו, כדבר החוסם ומפסיק אף בלא מקום שיש להפרידו, ומשמעות האמורה בקרקע, היינו, כמקום הנפרד אף בלא דבר החוסם.\u003c/span>"}, {"s": "h7", "h": "משמעות גדר דין גובה מבוי אי נימא דהוה דין בחלל ובחסרון דיותר מכ'"}, {"s": "p", "h": "ואי הוה דין בחלל יהיה גדרו דבעינן חלל שיכול לקבל משמעות המצמצמת והגובלת (הניתנת ע\"י קרקע וקורה כגבולותיו), ושיעור גובה הוא שיעור חלל שיש בו עצמו משמעות כזו (או שאין בו משמעות השוללת), שיועיל בו קרקע וקורה כתוספת משמעות (או שאינה נשללת עכ\"פ), ובאופן הפסול, היינו, יותר מכ', יש למצוא יש למצוא שתי חסרונות, או בחיוב דביותר מכ' יש בו משמעות דאף אי יהני ביה עניין קרקע שיש עליה קורה (היינו, שנאמר בו דחלל זה הוא חלל קרקע שיש עליה קורה), מאחר שיש בו גובה כ' אין למשמעות זו להועיל בו, אחר שבגובה זה כבר יצא מגדר חלל הנגבל ע\"י עניין זה. או בשלילי, דביותר מכ' הוי חלל שאין גבולותיו חשובים להתחבר יחד להיות בו גדר שיש בגבולו התחתון קרקע ובגבולו העליון קורה, והיינו, דאין דקורה על קרקע להועיל אלא במשמעותם יחד כגבולות החלל, ובזה החלל יתפרדו."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"426\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">26\u003c/sup>\u003cspan class=\"ca\" data-c=\"426\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ותראה בחילוק שני גדרים אלו באי הוה דין בחלל במשמעותו החיובית או בשלילית, דמיניה יהא גם חילוק במשמעות אחידות של חלל זה, היינו, דאי נימא שפסולו משום משמעותו  החיובית, ונימא דמשמעותו הנ\"ל (כמו הפשטות), היא בגובה ורוחב ואורך, הרי דלא בעינן אלא לבטל אחד מהן, היינו, דמשמעות חיובית הנ\"ל לא תמצא אלא בחלל באורך מבוי ורוחב טפח וגובה יותר מכ', ומיעוט איזה מהן כבר יתבטל משמעות זו, ולא ניבעי אלא למעט גובה במיעוט רוחב (אבל מיעוט אורך לא יהני דאין האורך אורך החלל אלא אורך המבוי, היינו, רוחב פתחו), ולא מצאנוהו בתלמוד דידן (היינו, דליתא למ\"ד דיהני מיעוט רוחב כל שהוא), אבל איתא בתלמוד דבני מערבא (פ\"א ה\"א) חברייא אמרין כל שהו הרי אין כאן גובה עשרים אמה על רוחב טפח. ע\"כ. אבל אי נימא דפסולו משום משמעות שלילית שיש בו אתיקון לחי וקורה, הרי שימצא גדר זה אכל משהו ומשהו גובה בנפרד להיותה משמעות שוללת אמה שיש בתיקון דקורה וקרקע להועיל.\u003c/span>"}, {"s": "h7", "h": "בדקדוק דברי רש\"י בגדר חסרון דיותר מכ' למ\"ד משום מחיצה"}, {"s": "p", "h": "ובהקדם זה נבוא לדקדק דברי רש\"י מה דעד אוקימתא דפליגי בקורה משום היכר או מחיצה, לא הזכיר חסרון דיותר מכ' רק משום היכר, ובאוקימתא דפליגי בקורה משום היכר או מחיצה, הוסיף דלמ\"ד משום מחיצה אין זה רק חסרון בהיכרא, אלא גם במחיצה עצמה, דאמרו רבנן דבטפי מעשרים לא אמרינן יורד וסותם, ויותר מזה יש לדקדק דלעיל כתב בטעמא דמ\"ד דבעינן ד\"ט ולא סגי בטפח, דמאחר דחודה הפנימי יורד וסותם, רוחב הקורה הוי חוץ לסתימה, ומשמע דאכן אמרינן יורד וסותם ואף במיעוט טפח גרידא, ומ\"ד דלא סגי בטפח משום היכר דלא מהני האי טפח להיכר דהמשתמשים במבוי (ואין לומר דמה שכתב דרוחב הקורה חוץ לסתימה, איירי אמבואות דעלמא דלא גבוהים יותר מכ', דהא כתב אמשתמשים במבוי שבנמוך הן, היינו, דאף דאיתא להגבהה דתחת הקורה, לא יהני למשתמשים במבוי וכו')."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1062\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">27\u003c/sup>\u003csup class=\"cb\" data-c=\"427\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">28\u003c/sup>\u003cspan class=\"ca\" data-c=\"1062 427\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ולכשתמצי לומר הרי הן שני גדרים בפסול דלמעלה מכ', דבאוקימתא קמא סברו למימר דאף אי נימא דקורה משום מחיצה, פסול דלמעלה מכ' אינו חסרון בגדרי מחיצה דקורה, אלא בהיכר קורה דעבדא להאי מחיצה, ובאוקימתא תניינא סברו דלמ\"ד קורה משום מחיצה, חסרון היכר קורה דאיכא בלמעלה מכ' הוא חסרון (גם) בהיכר מחיצה (וכמו דין מחיצות ניכרות), דביותר מכ' אף אי איכא למימר דיש קורה למבוי זה (היינו, ע\"י היכר דטפח), אין להאי קורה למיעבד מחיצה.\u003c/span>"}, {"s": "h7", "h": "חילוק משמעות בקורה משום מחיצה – גדר תיקון קורה להאי מ\"ד ותי' קושיית תוס'"}, {"s": "p", "h": "ואם אכן הרי שנמצא שתי משמעויות בהא דאמרינן קורה משום מחיצה, וכן נמצא גדר נוסף בתיקון קורה למ\"ד קורה משום מחיצה, והיינו כדאמרן לאוקימתא קמייתא, דגדר מחיצה דאיכא בקורה (היינו, דיש לקורה למיעבד מחיצה), אינו גדר אחד עם מה דמהני האי קורה לתיקוני למבוי (ודלא מהניא אלא בהיותה על גובה חלל מבוי עד כ'), ולכאורה ביאור זה כי אף דאית לקורה למיעבד מחיצה אקרקע שתחתיה בלא הגבלת גובה (היינו, ודאין היכרא יתרון או חסרון בקורה במשמעותה הנ\"ל), לא תהני האי קורה לגבי תיקון מבוי, ומשום דהיכר מבוי אינו אלא עד גובה כ', והיינו, דלא אמרו להיות המבוי ניתר ע\"י קורה ומשום מחיצה, אלא בהיות הקורה ניכרת כחלק מן המבוי."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"428\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">29\u003c/sup>\u003cspan class=\"ca\" data-c=\"428\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ותראה מה שיש בזה למעט במשמעות גדר מחיצה למ\"ד קורה משום מחיצה, והיינו, דבפשטות היה לומר דלמ\"ד קורה משום מחיצה, הא דמהני תיקון דקורה הוא משום דגזירת חכ' אמבוי משום דאתי לאחלופי, היא בהיות מבוי חסר מחיצות, ותיקון קורה הוא משום תועלת מחיצה דאית בה. אבל אי נימא דלא מהני קורה ביותר מכ' משום היכר, ואף באופן שיש להאי קורה למיעבד מחיצה, הרי בהכרח שבאופן המועיל אין זה משום מחיצה גרידא, אלא במשמעות האי קורה לגבי עניין אחר שהוא סיבת גזירת מבוי (היינו, ודאין מה דחיישינן דאתי לאחלופי נובע מחסרון מחיצות). ובזה יתורץ קושיית תוס' לאוקימתא קמא דאי סבר מ\"ד טפח קורה משום מחיצה אמאי לא בעינן מקום ד\"ט משום דאין מחיצה אלא וכו'.\u003c/span>"}, {"s": "p", "h": "ואם אכן, היינו, דפסול למעלה מכ' הוא על אף דאיתא לקורה דעבדא למחיצה, והאי מיעוט דעבדינן דלהווי היכר, אינו בהיכר קורה במשמעותה דעבדא מחיצה, אלא בהיכר מבוי שיש עליו קורה (וביחס לקורה, היינו, שתהא ניכרת במשמעותה כעליו דמבוי), הרי שיש להאי מיעוט להיות חשוב ביחס לזה. וא\"כ יהיה תליא במה דעבדא האי תקנתא דקורה למ\"ד קורה משום מחיצה בהיותה היכר דלא אתי לאחלופי."}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1063\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">30\u003c/sup>\u003cspan class=\"ca\" data-c=\"1063\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ד. בגדר תקנתא דקורה\u003c/span>"}, {"s": "h7", "h": "הקדם ביאור שייכות הנ\"ל עם עיקר סיבת הגזירה – בירור במח' אי חודה הפנימי או החיצון יורד וסותם"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"429\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">31\u003c/sup>\u003cspan class=\"ca\" data-c=\"429\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ולבאר שייכות זה עם עיקר סיבת הגזירה, וגדרה אתיקון הנרצה, יש לנו להקדים ביאור במח' אי חודו הפנימי יורד וסותם או החיצון, דלכאורה עיקר פלוגתתם צ\"ב, דמאחר שיש לחודה דקורה הרחבה טפח לרדת ולסתום, למה תהיה מוגבלת לסתימה מצד אחד, ולמה לא יהו שני חודיה יורדים וסותמים (וכדמצינו בפי תקרה), והיינו, לקולא (דלא אמרינן מחיצות להחמיר), וכן צ\"ב טעמיה דכל חד לומר דדווקא חוד זה יורד וסותם ולא זה.\u003c/span>"}, {"s": "h7", "h": "ביאור מח' בחוד היורד וסותם – אין המח' בקורה וחודה אלא בגדר תקנתא דקורה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1064\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">32\u003c/sup>\u003csup class=\"cb\" data-c=\"430\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">33\u003c/sup>\u003cspan class=\"ca\" data-c=\"1064 430\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ונראה דאמנם כן דיש לשני חודיה של קורה לרדת ולסתום, ופלוגתא דאיזה מהן יורד אינו בגדרי קורה וחודה, אלא הוא תליא בגדר תקנתא דקורה, ובהקדם מה שיש לחקור בגדר תיקון דקורה העומדת בראש המבוי, אם הוא תיקון במקומה של קורה (תחתיה), ושאר מבוי מיתקן ממילא, אחר שראשו מתוקן (ודמיא לגדר חציצה דמחיצה), או שהוא תיקון בכל המבוי, ומהני קורה אכולה מבוי כתיקון ראש דכולו (ודמיא לגדר היקף דמחיצה), ונראה דבזה תליא פלוגתא הנ\"ל, היינו, דאי לא הוי גדר תיקון דקורה רק אמקומה, הרי דלגבי מקומה הויא חשובה סתימה אף בחודה הפנימי (ולגבי מבוי יהיה משמעות רק בחודה הפנימי), אבל אי הוה גדר התיקון בכל המבוי, אין משמעות סתימה אלא בחודה החיצון.\u003c/span>"}, {"s": "h7", "h": "ביאור מח' היתר שימוש תחת הקורה – בתליית מח' הנ\"ל בחוד היורד וסותם"}, {"s": "p", "h": "וזה מה שתלו אי מותר להשתמש תחת הקורה או לא, במח' אי חודה החיצון יורד וסותם או חודה הפנימי, והיינו, דלכאורה היה לומר כדלעיל, דאף אי חודה הפנימי, יורד וסותם אין זה סתירה לומר דאף חודה החיצון, ואף אי גדר תיקון דקורה אמקומה, יהני האי תיקון לגבי מקומה בנפרד ממה דמהני לגבי מבוי, וביאורו דאמנם כאמור ודאי כמו דמהניא מפנימי מהניא מחיצון, אלא דמאחר שהוא גדר בתיקון קורה שתקנו חכמים, היינו, דלגבי מבוי מהניא כטפח החוסם, הרי דאין תחתיה דקורה מתוקן בתיקון מבוי שאמרו חכמים, ואף דיש לחודיה כולם לרדת ולסתום, אין זה מהני לגבי גזירה, דתיקון קורה הוא בהיות קורה ומקומה הנסתם כדרכה קיים בקצה המבוי, וזה אינו תחת הקורה (ואולי יהיה בזה נפק\"מ דאי איתא דשרי להשתמש על גבי קורה עצמה היא שרי אף למ\"ד חודו הפנימי. ויש לדחות)."}, {"s": "h7", "h": "בפסול דלמעלה מכ' דשיעורו משום היכר - גדר הנ\"ל ביחס למיעוט הנרצה"}, {"s": "p", "h": "ומעתה יבואר דאף פסול דלמעלה מכ' דשיעורו משום היכר, לא יתוקן במיעוט אלא במה שיש לו להועיל כנ\"ל, והיינו, דאי חודו החיצון יורד וסותם, וגדר קורה במקומה חשיב אכולה מבוי וכתחילתו, הרי דמעצם מה דתיקון קורה מהני להיכר ואף דאינו רק אטפח הראשון, י\"ל דאף לגבי מיעוט יהני מה שממעט טפח הראשון, שהיות טפח הראשון מהני לכולה מבוי כבר אמור בעצם התקנתא, אבל אי חודו הפנימי יורד וסותם, והרי רוחב קורה חוץ לסתימה, וכאמור גדר התיקון הוא במה שיש למקום סתום טפח בראש המבוי, להיות סתימה לכל המבוי, הרי שאין למצוא גדר היכר האמור ושנאמר דיו שיהיה במקומה של קורה, אלא הוא גדר במקום המבוי שיש מקום סתום זה בראשו, ומאחר שכן הרי דלגבי היכר זה בעינן שיהא המיעוט עביד מקום (בר הכירא) הנמצא בו משמעות שיש למצוא בשאר מבואות, והיינו, מקום מבוי במשמעות העצמית כמקום שימוש."}, {"s": "h7", "h": "גדר היכר למ\"ד אסור להשתמש תחת הקורה – דקדוק בגדר הנ\"ל לפמשנ\"ת"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1065\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">34\u003c/sup>\u003csup class=\"cb\" data-c=\"431\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">35\u003c/sup>\u003cspan class=\"ca\" data-c=\"1065 431\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ובזה יש להוסיף דזה שאנו אומרים דלמ\"ד אסור להשמתמש תחת הקורה דחודה הפנימי וכו' צריך שיהא גדר היכר בקורה למבוי (היינו, שלא תהא חשובה הקורה ניכרת אלא בהיותה ניכרת למבוי, וכאמור משמעות מבוי בזה הוא כמקום שימוש, ותהא נבחנת בהיותה ניכרת למשתמשים במבוי), הרי יש בזה תוספת גדר היכר על עיקר היכר דקורה עצמה, שלא נמצאה לאידך מ\"ד, והיינו, דלמ\"ד מותר להשתמש תחת הקורה דחודה החיצון וכו' ולפמשנ\"ת דמשמעות היות קורה בראש מבוי היא בכל המבוי, הרי שאין להבחין גדר מקום שתחת הקורה ממקום שאר מבוי במשמעותם העצמית, ולא נמצא הבחנת מקום שתחת הקורה אלא במה שהיא תחת הקורה, וממילא הרי שלא נמצא דין היכר קורה אלא בקורה עצמה, ויבואר מה דלא בעינן למיעוט אלא תחת הקורה, שביחס לקורה עצמה מהיכי תיתי לומר שנצטרך שתהא נבחנת ממקומות אחרים (וכאמור דמה שדי לנו במקום טפח הוא נובע מעיקר דין קורה דלא בעינא דתהא אלא טפח), אבל למ\"ד דאסור וכו' דחודה החיצון וכו' הרי שאין מקום שתחת הקורה בגדר אחד עם מקום הניתר על ידה, דמקום שתחת הקורה הוא כמקום מחיצה עצמה (כעובי מחיצה), ומקום המבוי הוא מקום הנפעל מן מחיצה (היינו, מקום הנמחץ על ידה), וגדר היכר האמור בקורה הוא ממקום הנפעל על ידה (ודוגמתו בסוכה דאדם יודע שהוא דר בסוכה, היינו, דיש בראיית הסכך תוספת משמעות בישיבת מקום הסוכה), דהוא חשוב מקום קורה, ובעינן שתהא ניכרת למבוי, ואמנם כאמור דעיקר היכר דבר מלתחת הוא ממקום שתחתיו, אבל מאחר דעיקר משמעות קורה ותחתיה הוא במה שיש בהם סתימת מקום המבוי, צריך שימשך מקום הקורה (החשוב כן ע\"י מיעוט חלל מכ') לתוך המבוי.\u003c/span>"}, {"s": "h7", "h": "\u003csup class=\"cb\" data-c=\"432\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">36\u003c/sup>\u003cspan class=\"ca\" data-c=\"432\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">שיווי גדר היכר דמיעוט שתחת הקורה ושאינו - בתועלת המשכת המיעוט שלא תחת הקורה\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1066\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">37\u003c/sup>\u003csup class=\"cb\" data-c=\"433\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">38\u003c/sup>\u003cspan class=\"ca\" data-c=\"1066 433\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ובזה יש לדקדק דאין גדר היכר דאיכא במיעוט הנמשך לתוך המבוי שווה לגדר היכר דאיכא במיעוט שתחת הקורה, דהא ודאי שעיקר היכר דבר מלתחת הוא מתחתיו ביושר, וגם אין שיעור היכר בכ' נמדד אלא בזה (היינו, דלעומד בקצה הפנימי של מיעוט ד\"ט תהא מדידת כ' בתוספת אלכסון דטפח וחומש לחוד הפנימי או טפח ושלושה חומשים לחוד החיצון), ובהכרח דאין המשכת מיעוט האמורה לתוך המבוי מהני להיכר קורה דשיעורו בכ' כמיעוט דתחת הקורה, וצ\"ב א\"כ מה מהני המשכה זו.\u003c/span>"}, {"s": "p", "h": "והנראה לומר דאף אמנם דלא מהני מקום המשכה זו כמקום שתחת הקורה, אבל מהני לגבי מקום עצמו, היינו, מה דמקום זה שיש בו (בחלק טפח שתחת הקורה) היכר קורה, יש בו גם שימוש מבוי, וגדר זה הוא לפמשנ\"ת דמה דבעינא דליהווי היכר למשתמשים במבוי הוא מחמת שהן מקום הקורה, היינו, דקורה דעבידא לסתימה היא לסתימת מקום זה, ואף דאיכא למיעוט מקום דתחת הקורה להועיל לגבי מקום הסתימה, לא יחשב מקום שתחת הקורה לגבי סתימה אלא בחיבורו עם מקום שהיא סותמת, ותהא המשכת המיעוט לתוך המבוי דהוא מקום הנסתם מועילה לגבי סתימה הנעשית במקום שתחת הקורה דהיא סותמת מקום שלידה."}, {"s": "h7", "h": "חילוק גדר בשיעור ד\"ט באוקימתא דקורה משום מחיצה מאוקימתא דלעיל"}, {"s": "p", "h": "ואם כנים הדברים הרי דשאני גדר ד\"ט האמור בהאי אוקימתא מבאוקימתא דפליגי בקורה משום היכר או משום מחיצה, דלאוקימתא קמא גדר ד\"ט אינם ד\"ט דמקום שימוש אלא ד\"ט דמקום סתם (ומה דמהני שיהא מקום סתימה שתחת הקורה מחובר עם מקום הנסתם), אבל לאוקימתא דקורה משום מחיצה היה גדר ד\"ט דלהיווי מחיצה למקום שימוש וכו'."}, {"s": "p", "h": "ובזה יבואר מה דעכ\"פ בעינן למיעוט טפח שתחת הקורה, וכן יבואר מה דמהני האי טפח לאיצטרופי לד\"ט אע\"ג דהא דבעינא להו (ולא סגי בטפח) הוא משום מקום המותר להשתמש. ויבוארו דברי רש\"י בדקדוק חמור."}, {"s": "p", "h": "והנה גדר היכר שיש במיעוט הנ\"ל, היינו, מיעוט דתחת הקורה, זה הוא בהיכר קורה שלעצמה, וחשיב כל חלק דמיעוט טפח כנגד קורה שמעליו, וחשיבי כל החלקים הנ\"ל דבר אחד להיותם מקיימי קורה הניכרת ודהיא בשיעור טפח."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1067\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">39\u003c/sup>\u003cspan class=\"ca\" data-c=\"1067\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ולא פליגי אביי ורב יוסף אלא ביחס להיכר דהנ\"ל, היינו, קורה אחלל (ודחשיבא קורה במה שהיא קורה דחלל, בחלל שאינו יותר מכ'), ודחשיבא תחתיה פתח, כמה צריך שימשך המיעוט דיהני להיחשב האי פתח פיתחא דמבוי. ותם העת, ועט הונם, וען ינאם, מתנת חנם.\u003c/span>"}], "comments": [{"id": "1052", "n": 1, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-255 | סוג: קטע חסר | מקור: 01_גרסאות_הספר/מלאכת שבת רשויות עירובי חצירות תחומין.pdf\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"סוגיא דרוחב מיעוט (ד:)...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>ואגב נפרש דברי הגמ' והרש\"י במח' אביי ור\"י (ד:) ברוחב מיעוט דהבא למעטו מכ' רחבו של מיעוט להרחיבו לתוך המבוי כמה בעינן.\u003c/p>\u003cp>הצעת הסוגיא\u003c/p>"}, {"id": "1053", "n": 2, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-256 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (5 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. במה דמשמע דלכ\"ע בעינן טפח תחת הקורה ודהאי טפח חשיב אחד מד\"ט\u003c/p>\u003cp>2. דאשכחן הכירא מלגיו או לבר אבל מלתחת הקורה מאן דכר שמיה\u003c/p>\u003cp>3. שינוי לשון רש\"י בכיון דאפיקתיה וכו' בתרי לישני דגמ'\u003c/p>\u003cp>4. בתי' תוס' דאף למ\"ד משום מחיצה לא בעינן לד\"ט כחילוק שכ' ברש\"י לק' דהכא איתיה לדופן\u003c/p>\u003cp>5. במה דלא נתבאר גדר היכר של מטה\u003c/p>"}, {"id": "1054", "n": 3, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-257 | סוג: קטע חסר | מקור: 09_קבצי_הרחבה_ומקורות/רוחב מיעוט.docx\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"והנה צ\"ב באוקימתא דכ\"ע קסברי מותר להשתמש תחת הקורה וקמיפלגי בקורה אי הוי משום היכר או משום מחיצה, וכתב ברש\"י ב...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>155 [רגיל] דאשכחן הכירא מלגיו או לבר אבל מלתחת הקורה מאן דכר שמיה\u003c/p>"}, {"id": "411", "n": 4, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0844 | רש״י „בכניסתן כשמשתמשין” – לשון משולבת ולא בהכרח שני מצבי דין | חומרה: בינונית-גבוהה רש״י בעירובין ה ע״א אכן כותב „הרי יש כאן היכר בכניסתן כשמשתמשין תחת הקורה”. אפשר לדקדק בין עצם הכניסה לבין השימוש לאחר הכניסה, אך אין הכרח שרש״י מונה כאן שני מצבים הלכתיים נפרדים; אפשר שהכוונה להיכר שנוצר בכניסת המשתמשים, בעת שהם משתמשים תחת הקורה. כדי לבסס את ההבחנה בין עמידה, הילוך ושימוש, כדאי להביא את לשון רש״י בשלמותה ואת ההקשר שבו נאמרה, ולציין במדויק את המקור בשבת ק ע״א שעליו נסמך החילוק „הילוך/תשמיש”.\u003c/p>"}, {"id": "412", "n": 5, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0845 | „היכר של מטה” אינו זהה ל„היכרא מלגיו/מלבר” | חומרה: גבוהה יש כאן שתי סוגיות סמוכות אך שונות. בעירובין ה ע״א הוצעה אוקימתא של „היכר של מטה” לעומת „היכר של מעלה” כדי להסביר את שיעור רוחב המיעוט; בעירובין ח ע״ב נדונה שאלת השימוש תחת הקורה, וההעמדה היא „היכירא מלגיו” או „מלבר”, או לחלופין איזה חוד יורד וסותם. אין לזהות מראש „מטה/מעלה” עם „פנים/חוץ”: הראשון נוגע למקום שבו נעשה המיעוט וליחסו להיכר העליון, והשני לצד הקורה שממנו נקבע ההיכר או קו המחיצה. מומלץ להציג את צירי הדיון בטבלה נפרדת, ורק לאחר מכן לבדוק אם המחבר מוצא ביניהם קשר.\u003c/p>"}, {"id": "1055", "n": 6, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-258 | סוג: קטע חסר | מקור: 04_רשויות/רשויות - סוגיות - עותק 4.txt\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"ועוד יש להקשות אמה דכתב דמ\"ד אסור להשתמש, והיינו משום דחודו הפנימי יורד וסותם, בעי ד\"ט, דכיון דאפיקתיה מתחת הק...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>159 [רגיל] שינוי לשון רש\"י בכיון דאפיקתיה וכו' בתרי לישני דגמ'\u003c/p>"}, {"id": "413", "n": 7, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0846 | מיעוט של ארבעה טפחים – להפריד בין הטפח שתחת הקורה לבין ההמשכה פנימה | חומרה: גבוהה רש״י בעירובין ה ע״א מפרש את שיעור הטפח „כנגד רחבה של קורה ותחתיה”, ואילו למאן דאמר ארבעה, כאשר חודו הפנימי יורד וסותם, „צריך שימשך לתוך המבוי” כדי שהקורה תיראה למשתמשים בגובה המיעוט. נמצא שהארבעה אינם בהכרח ארבעה טפחים כולם מתחת לקורה: הטפח שמתחתיה וההמשכה לתוך המבוי ממלאים תפקידים שונים. כדאי לנסח זאת במפורש, ולסמן איזה חלק מן המיעוט מצטרף לשיעור ארבעה ואיזה חלק יוצר את ההיכר למשתמשים. כך תתברר גם קושיית המחבר כיצד מצטרף טפח למקום שאסור להשתמש בו.\u003c/p>"}, {"id": "414", "n": 8, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0847 | שני טעמי רש״י לשיעור ארבעה – אין למזגם לגדר אחד | חומרה: גבוהה ההשוואה מדויקת וחשובה, אך יש להקפיד על מיקומה: בדיבור „ומאן דאמר ארבעה” רש״י מסביר שהמיעוט צריך להימשך לתוך המבוי כדי שיהיה למשתמשים היכר בגובה שבו הם משתמשים, ומשום שהוציאו את המיעוט מתחת לקורה צריך „מקום הניכר וחשוב”. בדיבור „גזירה שמא יפחות” הוא מסביר שהעמידו על ארבעה מפני ש„דחשיבי בכל דוכתא”. אלו שני הסברים באוקימתות שונות; אין הכרח שהם שני שלבים מצטברים באותו דין. מומלץ לציין בכל פעם לאיזו אוקימתא ולמחלוקת מסוימת ברש״י מתייחס הדיוק, ולא להציג את „חשיבות המקום” כטעם אחיד לכל ארבעת הטפחים.\u003c/p>"}, {"id": "415", "n": 9, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0848 | מיקום ההיכר – להבחין בין מיקום המיעוט לבין צד הצופה | חומרה: גבוהה הקושיה מערבת שני צירים גאומטריים: היכן נמצא המיעוט ביחס לקורה ולאורך המבוי, ומאיזה צד של הקורה ניכר ההיכר (מבפנים או מבחוץ). בעירובין ח ע״ב „מלגיו/מלבר” מתייחס לצד הקורה שממנו ניכר ההיכר, ואילו כאן „היכר של מטה/מעלה” מתייחס ליחס שבין המיעוט התחתון להיכר הקורה העליון. גם אם יש קשר בין הצירים, הוא טעון הוכחה. כדאי להוסיף שרטוט של חתך המבוי ושל מבט לאורך המבוי, ולסמן בנפרד את נקודת המיעוט, עובי הקורה, מקום המשתמשים וכיוון הראייה.\u003c/p>"}, {"id": "416", "n": 10, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0849 | חשש „אתי לאחלופי” – היכר בפתח אינו מחייב היכר בכל נקודה | חומרה: גבוהה הקושיה מניחה שאם יש שימוש בכל המבוי, נדרש היכר נפרד בכל מקום שימוש. אולם אפשר שתקנת ההיכר נועדה לזהות את הכניסה או את גבול המבוי, והיכר בפתח משפיע על הבנת המקום כולו. כך משמע לכאורה מלשון רש״י בה ע״א: „יש כאן היכר בכניסתן”. לכן אין להסיק מעצם השימוש בכל אורך המבוי שההיכר מוכרח להתקיים לאורך כולו. יש לברר תחילה אם חשש ההחלפה הוא בכל מקום שימוש או בזיהוי המבוי בעת הכניסה; רק לפי הגדרה זו ניתן להעמיד את הקושיה על שיעור המיעוט המצומצם.\u003c/p>"}, {"id": "1056", "n": 11, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-259 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (4 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. חוד ופי ופני דבר האמורים מכח דבר ושיעורו\u003c/p>\u003cp>2. המתחייב לפי\"ז דעכ\"פ בעינן מיעוט תחת הקורה\u003c/p>\u003cp>3. היינו טעמא דלכ\"ע לא בעינן היכר בכל המבוי\u003c/p>\u003cp>4. בחלקי דין גובה מבוי ומה שיש לחקור בזה\u003c/p>"}, {"id": "417", "n": 12, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0850 | „כמה ממעט” – לבסס את הניתוח על פירוש רש״י לפני ההפשטה המושגית | חומרה: בינונית-גבוהה רש״י בעירובין ד ע״ב מפרש „כמה ממעט” – „כמה יגביה הקרקע”, ואת „כמה דצריך ליה” – „עד שלא יהא החלל יותר על עשרים”; לאחר מכן „רחבו” הוא רוחב המיעוט לתוך אורך המבוי. זהו תחילה בירור מעשי של גובה המיעוט ושל רוחבו, ורק לאחר מכן ניתן לבנות ממנו חקירה מושגית בשאלה אם המיעוט נמדד ביחס לחלל או כגדר בפני עצמו. כדאי להציג תחילה את קריאת רש״י, ואז לסמן במפורש שהחלוקה בין „גדר המיעוט” לבין „החלל המתמעט” היא חידוש המחבר ולא מסקנת לשון הגמרא. בפסקה גם תיקון לשוני: „ואזה תמהו” אינו ברור, ויש לבדוק אם הכוונה „ועל זה תמהו”.\u003c/p>"}, {"id": "418", "n": 13, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0851 | דיוק שינויי לשון רש״י – מסקנה אפשרית, לא הוכחה לשינוי במעמד התקנה | חומרה: גבוהה רש״י אכן משנה לשונו בין „קורה שתיקנו חכמים למבוי משום היכר” לבין „קורה המתרת במבוי טעמא משום מחיצה”. עם זאת, שינוי הניסוח לבדו אינו מוכיח שלמ״ד משום מחיצה הקורה אינה חלק מתקנת חכמים, או שהמחיצה פועלת בלי תקנה. אפשר שרש״י רק מנסח את שני הצדדים לפי תפקיד הקורה בכל אוקימתא. כדי לבסס את הקריאה המוצעת יש להראות מה נובע ממנה בהמשך לשון רש״י, ובעיקר כיצד היא מתיישבת עם העובדה שגם למ״ד משום מחיצה עדיין מדובר בתיקון מבוי מדרבנן.\u003c/p>"}, {"id": "419", "n": 14, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-06", "h": "\u003cp>S-20261106-204 | חומרה: גבוהה | קטגוריה: קורה משום מחיצה — מקור ההיכר הנדרש למניעת החלפה, כשאינו נובע מעצם הקורה כמחיצה. יש להבחין בין טעם הקורה כמחיצה לבין הצורך בהיכר כדי שלא יבואו להתיר רשות הרבים. ברש״י בעירובין ה ע״א מופיעות שתי העמדות: למ״ד משום היכר — הקורה שתיקנו חכמים היא עצמה סימן שלא יבואו להתיר רשות הרבים; למ״ד משום מחיצה — חודה החיצון יורד וסותם והקורה מתירה מכוח דין מחיצה. המחבר מציע שגם בשיטת מחיצה נדרש היכר, אך הוא אינו נובע מן הקורה עצמה במשמעותה כמחיצה, אלא מעצם העובדה שמבוי אינו מותר אלא כשהוא מתוקן בקורה. זהו חידוש מושגי שאינו מפורש בלשון רש״י, ויש לבסס מדוע התנאי ההלכתי שהמבוי לא יותר בלי קורה יוצר היכר ממשי המונע החלפה ברשות הרבים. בפרט, יש להסביר מדוע היכר זה אינו מתקיים גם במחיצה רגילה או בשלוש/ארבע מחיצות גמורות, ומהו ההבדל בין סימן חזותי שבני אדם רואים לבין היכר הנובע ממעמד התיקון ההלכתי. כדאי גם להבחין בין עצם הצורך בהיכר — שעשוי להיות מוסכם לכל השיטות — לבין השאלה מהו הרכיב שמייצר אותו בכל אחת מהעמדות.\u003c/p>"}, {"id": "420", "n": 15, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0852 | ארבעה טפחים ברשות היחיד – שיעור במקום ולא בהכרח במחיצה | חומרה: גבוהה הקושיה על רש״י חזקה: שיעור ארבעה טפחים ברשות היחיד נאמר על מקום/חלל הראוי להיחשב רשות, ולא בהכרח על כל קטע של מחיצה בפני עצמו. עם זאת, רש״י משתמש בו כאנלוגיה לשאלה אם ניתן לומר „חודו יורד וסותם” כאשר החלל שמתחת לקורה צר מארבעה. לכן יש להבחין בין מקור השיעור ברשות היחיד לבין ההיקש שרש״י עושה ממנו כאן. כדאי להעמיד דוגמה גאומטרית מדויקת של מקום שאורכו ארבעה ורוחבו משתנה, ולברר אם הוא עדיין רשות היחיד; רק כך יתברר אם הטענה ש„ד׳ טפחים” הוא גדר של מקום ולא של מחיצה אכן דוחה את ראיית רש״י.\u003c/p>"}, {"id": "421", "n": 16, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0853 | גזוזטראות – לציין את מבנה המקרה ואת השיעור הנדון | חומרה: בינונית-גבוהה המקור שרש״י מפנה אליו הוא עירובין פו ע״ב (ובהמשך פז ע״א), בדין גזוזטרא שעל המים והיתר „כוף וגוד”. הברייתא עוסקת בגזוזטרא שיש בה ארבע אמות על ארבע אמות, ובחקיקת פתח של ארבעה על ארבעה טפחים; אין לערבב בין שיעור שטח הגזוזטרא, שיעור החלל שבפתח, וגובה המחיצה הנלמדת מדין „כוף וגוד”. כדאי לצטט את לשון הסוגיה ולציין במפורש איזה מארבעת השיעורים רש״י מביא כראיה למיעוט הקורה. כך תתברר גם השאלה האם מדובר בחסרון במחיצה עצמה או בחסרון בחלל שהמחיצה אמורה להקיף.\u003c/p>"}, {"id": "422", "n": 17, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0854 | הטפח שתחת הקורה – להבחין בין רוחב הקורה לאורך המיעוט | חומרה: גבוהה הדיוק שרוחב הקורה הוא טפח ושצריך מיעוט מתחתיה לכל רוחבה תואם את פירוש רש״י „טפח כנגד רחבה של קורה ותחתיה”. אולם בהמשך הסוגיה רש״י מפרש את ארבעת הטפחים כהמשכה „לתוך אורך המבוי”. אלה שני ממדים שונים: רוחב הקורה לרוחב הפתח, לעומת אורך המיעוט הנמשך פנימה. מומלץ להוסיף שרטוט חתך ותכנית מלמעלה: הטפח שמתחת לקורה הוא רוחב/רצועה התואמת את הקורה; ההמשכה של שלושה טפחים נוספים היא לאורך המבוי. בלי ההפרדה, הביטוי „תחת כל רוחב הקורה” עלול להתפרש כאילו כל שיעור ארבעת הטפחים מונח מתחת לקורה.\u003c/p>"}, {"id": "423", "n": 18, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0855 | היכר נקודתי בפתח והשלכתו על כל המבוי – להציג את החידוש כמודל | חומרה: גבוהה הטענה שקורה המונחת בפתח מקבלת חשיבות „אכל מבוי” היא ציר מרכזי במהלך, אך יש להבחין בין שני דברים: הקורה פועלת להתיר את המבוי כולו, ואילו ההיכר עצמו נעשה בנקודת הכניסה. אין מכאן בהכרח שהמיעוט הפיזי שתחת הקורה יוצר מקום שימוש או תיקון בכל אורך המבוי. כדאי לנסח במפורש שהמעבר מחשיבות הפתח לחשיבות התיקון בכל המבוי הוא מודל מושגי של המחבר, ולבדוק אם הוא מסביר גם את הצורך בהמשכת המיעוט פנימה למאן דאמר ארבעה.\u003c/p>"}, {"id": "1057", "n": 19, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-260 | סוג: קטע חסר | מקור: 04_רשויות/רשויות - סוגיות - עותק 4.txt\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"אלא דמאחר דהאי קורה לאו לתיקוניה מחיצות המבוי, ומשמעותה אפתח אינו ביחס לגידור המבוי, אלא במה שיש להועיל ביחס ל...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>195 [רגיל] בחלקי דין גובה מבוי ומה שיש לחקור בזה\u003c/p>"}, {"id": "1058", "n": 20, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-261 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (5 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. בגדר הנ\"ל אי הוה דין בקרקע ובחסרון דיותר מכ'\u003c/p>\u003cp>2. בגדר הנ\"ל אי הוה דין בקורה ובחסרון דיותר מכ'\u003c/p>\u003cp>3. בגדר הנ\"ל אי הוה דין בחלל ובחסרון דיותר מכ'\u003c/p>\u003cp>4. שתי משמעויות בהא דאמרינן קורה משום מחיצה ותי' קושיית תוס'\u003c/p>\u003cp>5. והא תליא במה דעבדא האי תקנתא דקורה\u003c/p>"}, {"id": "1059", "n": 21, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-262 | סוג: קטע חסר | מקור: 04_רשויות/רשויות - סוגיות - עותק 4.txt\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"וביאור זה צריך להקדמה, דהנה דין גובה מבוי הוא דין בשייכות שני דברים, היינו, קרקע, קורה, וגובה חלל כ' המשייכם, ...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>197 [רגיל] בגדר הנ\"ל אי הוה דין בקרקע ובחסרון דיותר מכ'\u003c/p>"}, {"id": "424", "n": 22, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0856 | שלושת רכיבי גובה המבוי – לחדד את החלוקה הלוגית | חומרה: בינונית-גבוהה הפסקה פותחת ב„שני דברים” – קרקע וקורה – ומונה לאחר מכן שלוש אפשרויות: דין בקרקע, דין בקורה, או דין ביחס שביניהם (חלל הגובה). זו חלוקה אפשרית, אך החלל אינו עצם שלישי המקביל לקרקע ולקורה אלא היחס/המרחק ביניהם. מומלץ לנסח: שני רכיבים פיזיים ויחס מרחבי אחד; ולציין שכל אחת משלוש האפשרויות מגדירה את נושא הדין באופן אחר. אחרת עלול להיווצר רושם שהחלל הוא „דבר” שלישי עצמאי, אף שהמחבר מבקש לבחון דין שבשייכות שני דברים.\u003c/p>"}, {"id": "1060", "n": 23, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-263 | סוג: קטע חסר | מקור: 04_רשויות/רשויות - סוגיות - עותק 4.txt\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"היכר קרקע, היינו, דאין היכר קרקע אלא עד עשרים, ואנן בעינן שתהא הקורה תוך היכר של קרקע, היינו, דיש לרואה לראות ...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>201 [רגיל] בגדר הנ\"ל אי הוה דין בקורה ובחסרון דיותר מכ'\u003c/p>"}, {"id": "425", "n": 24, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-06", "h": "\u003cp>S-20261106-205 | חומרה: גבוהה | קטגוריה: השפעת הקורה על הקרקע לעומת היכר הקורה ביחס לקרקע — האם אלה שני מנגנונים חלופיים או מצטברים. בפסקה זו אתה מציע שני חסרונות אפשריים כאשר שיעור הגובה הוא דין בקורה: (א) הקרקע אינה נחשבת עוד ״תחת״ הקורה, ולכן אין היא נתונה להשפעתה; (ב) הקרקע אינה נמצאת בתוך היכר הקורה, ולכן הרואה אינו תופס את פעולת הקורה ביחס אליה. אלה שני מנגנונים שאינם מאותו סוג: הראשון הוא יחס מרחבי/פעולתי בין הקורה לקרקע, והשני הוא תנאי של הכרה חזותית וייחוס הקורה לקרקע. יש להבהיר אם מדובר בשתי חלופות שמסבירות את הפסול למעלה מעשרים, או בשני חסרונות מצטברים. אם אלה חלופות, מהו המקור לכל אחת ומהי הנפקא מינה ביניהן? אם הן מצטברות, מדוע נדרשים שתיהן, ומה קורה במקום שבו הקרקע עדיין נחשבת תחת הקורה אך אינה בתוך ההיכר שלה, או להפך? יש גם לקשר את ההבחנה לחלוקה הקודמת בין קרקע, קורה וחלל: E-0856 כבר מבקשת להגדיר את שלושת רכיבי הניתוח, ואילו כאן נדרש לברר מהותית את ההבדל בין השפעת הקורה לבין היכר הקורה, ולא להניח שהמילים ״תחת הקורה״ ו״תוך היכר הקורה״ מציינות אותו תנאי.\u003c/p>"}, {"id": "1061", "n": 25, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-264 | סוג: קטע חסר | מקור: 04_רשויות/רשויות - סוגיות - עותק 4.txt\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"ותראה חילוק שני פנים אלו, שהוא נובע מהבדל שבעצם משמעות קורה מקרקע, היינו, דאי איתא לגדר קורה שלעצמה, פירושו, ש...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>204 [רגיל] בגדר הנ\"ל אי הוה דין בחלל ובחסרון דיותר מכ'\u003c/p>"}, {"id": "426", "n": 26, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0857 | מיעוט ברוחב כלשהו – להבחין בין הבבלי לירושלמי | חומרה: גבוהה ההפניה לירושלמי עירובין פ״א ה״א חשובה: שם מובאת שיטת חברייא „כל שהוא”, בנימוק „הרי אין כאן גובה עשרים אמה על רוחב טפח”. אולם אין להציג את הירושלמי רק כהוכחה לכך שמיעוט ברוחב כלשהו מבטל את החלל; זהו דיון במבנה השיעור וביחס שבין גובה עשרים לרוחב טפח, ויש לברר את נוסח הירושלמי ואת ההקשר של הדעות החולקות. כדאי להעמיד בטבלה את שיטת הבבלי (רב יוסף טפח, אביי ארבעה) מול שיטת הירושלמי, ולציין מהו בדיוק המשתנה הגאומטרי שלדעת כל שיטה מגדיר את הפסול.\u003c/p>"}, {"id": "1062", "n": 27, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-265 | סוג: קטע חסר | מקור: 04_רשויות/רשויות - סוגיות - עותק 4.txt\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"ולכשתמצי לומר הרי הן שני גדרים בפסול דלמעלה מכ', דבאוקימתא קמא סברו למימר דאף אי נימא דקורה משום מחיצה, פסול ד...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>211 [רגיל] שתי משמעויות בהא דאמרינן קורה משום מחיצה ותי' קושיית תוס'\u003c/p>"}, {"id": "427", "n": 28, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0858 | שתי האוקימתות ברש״י – לא להפוך חילוק הסברי להכרח של שני דינים | חומרה: גבוהה החלוקה בין חסרון בהיכר בלבד לבין חסרון גם ביכולת הקורה לפעול מחיצה היא שחזור עיוני אפשרי של שתי האוקימתות. עם זאת, יש להיזהר: באוקימתא הראשונה הגמרא מציגה מחלוקת אם קורה משום היכר או משום מחיצה; באוקימתא אחרת כולם מודים שהיא משום היכר ונחלקים בהיכר של מטה/מעלה; ובשלישית כולם מודים בהיכר ונחלקים בגזירה שמא יפחות. אין כאן בהכרח שתי הגדרות מצטברות של פסול למעלה מעשרים, אלא חלופות להסברת מחלוקת רב יוסף ואביי. מומלץ למפות תחילה כל אוקימתא בנפרד ולציין איזו מהן מניחה את דברי רש״י שאתה מנתח.\u003c/p>"}, {"id": "428", "n": 29, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0859 | תירוץ קושיית תוספות – נדרש עיון בלשונם ולא רק במסקנת רש״י | חומרה: גבוהה הפתרון המוצע לקושיית תוספות תלוי בהבחנה בין „מחיצה” שיורדת וסותמת לבין „היכר מבוי שיש עליו קורה”. יש להביא את לשון התוספות במלואה ולסמן מה בדיוק קשה להם: מדוע למאן דאמר קורה משום מחיצה אין צורך בארבעה, לאור הכלל שאין מחיצה לחלל פחות מארבעה. לאחר מכן יש להראות כיצד המודל החדש מסביר את שיעור הטפח, ולא רק מדוע הוא מאפשר להימנע מן ההיקש לרשות היחיד. רצוי גם להבחין בין „קורה משום מחיצה” בגדר הסוגיה כאן לבין דין פי תקרה יורד וסותם במקומות אחרים.\u003c/p>"}, {"id": "1063", "n": 30, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-266 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (3 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. ביאור מה דתלו דין אי מותר להשתמש תחת הקורה בהנ\"ל\u003c/p>\u003cp>2. הצ\"ב להנ\"ל בתועלת המשכת המיעוט למקום שלא תחת הקורה\u003c/p>\u003cp>3. גדר האי מקום כמקום הקורה (ולא חלק ממקום המבוי)\u003c/p>"}, {"id": "429", "n": 31, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0860 | שני חודי הקורה – השאלה היא מיקום הגבול ההלכתי | חומרה: גבוהה בסוגיית עירובין ח ע״ב המחלוקת אינה בהכרח אם מבחינה פיזית שני צדי הקורה מסוגלים ליצור ירידה, אלא היכן נקבע קו הגבול ההלכתי: בחודה הפנימי או בחודה החיצון. לפי צד אחד השטח שתחת הקורה נמצא מחוץ למחיצה, ולפי הצד האחר הוא בתוכה. לכן אין די בטענה ששני החודים „יכולים” לרדת; צריך להסביר מדוע לצורך הגדרת רשות אחת נקבע גבול אחד ולא שני גבולות היוצרים רצועה נפרדת תחת עובי הקורה. זו נקודת המפתח לבירור, ולא עצם האפשרות ההנדסית של ירידת שני הצדדים.\u003c/p>"}, {"id": "1064", "n": 32, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-267 | סוג: קטע חסר | מקור: 04_רשויות/רשויות - סוגיות - עותק 4.txt\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"ונראה דאמנם כן דיש לשני חודיה של קורה לרדת ולסתום, ופלוגתא דאיזה מהן יורד אינו בגדרי קורה וחודה, אלא הוא תליא ...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>221 [רגיל] ביאור מה דתלו דין אי מותר להשתמש תחת הקורה בהנ\"ל\u003c/p>"}, {"id": "430", "n": 33, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0861 | הקישור בין היקף התיקון לבין חוד הקורה – חידוש שדורש הוכחה | חומרה: גבוהה החילוק בין תיקון מקומי תחת הקורה לבין תיקון המתייחס לכל המבוי הוא הצעה עיונית, אך אין הוא נאמר במפורש בסוגיית עירובין ח ע״ב. הסוגיה תולה את ההיתר להשתמש תחת הקורה בשאלה אם ההיכר מלגיו/מלבר או אם חודה הפנימי/החיצון יורד וסותם. כדי לקשור זאת להיקף תיקון המבוי, צריך להראות מדוע חוד חיצון מצביע על תיקון כללי של המבוי וחוד פנימי על תיקון מקומי, ומהו המקור לכך שקורה בפתח מתקנת „את כל המבוי” ולא רק מתירה אותו מכוח היותה בפתחו.\u003c/p>"}, {"id": "1065", "n": 34, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-268 | סוג: קטע חסר | מקור: 04_רשויות/רשויות - סוגיות - עותק 4.txt\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"ובזה יש להוסיף דזה שאנו אומרים דלמ\"ד אסור להשמתמש תחת הקורה דחודה הפנימי וכו' צריך שיהא גדר היכר בקורה למבוי (...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>227 [רגיל] הצ\"ב להנ\"ל בתועלת המשכת המיעוט למקום שלא תחת הקורה\u003c/p>"}, {"id": "431", "n": 35, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0862 | עובי הקורה כמקום מחיצה לעומת החלל הניתר – להמחיש את המודל | חומרה: גבוהה ההבחנה בין הרצועה שמתחת לעובי הקורה לבין חלל המבוי הניתר באמצעותה עשויה ליישב חלק מן הקושיות, אך יש להגדיר את המונחים הגאומטריים. „תחת הקורה” הוא שטח אופקי שרוחבו כעובי הקורה; „מקום המבוי” הוא החלל שמעבר לקו המחיצה; ואילו „המקום הנפעל מן המחיצה” הוא האזור שהמחיצה מגדרת. מומלץ להוסיף תרשים שבו מסומנים חודה הפנימי, חודה החיצון, שטח הקורה, רצועת המיעוט והחלל הניתר. כך יהיה אפשר לבדוק אם ההיכר למשתמשים אכן צריך להימשך לתוך המבוי, או שמא די בהיכר בפתח כדברי רש״י.\u003c/p>"}, {"id": "432", "n": 36, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-08", "h": "\u003cp>S-20261108-001 | חומרה: גבוהה | קטגוריה: סתירה פנימית בין איסור שימוש תחת הקורה לבין חודה החיצון. בפסקה הקודמת (P02555) נאמר תחילה שלמאן דאמר אסור להשתמש תחת הקורה חודה הפנימי יורד וסותם. בהמשך אותה פסקה נכתב שוב „למ״ד דאסור ... דחודה החיצון”. נוצר כאן היפוך פנימי: ברש״י עירובין ה ע״א, ד״ה „ומאן דאמר ארבעה קסבר אסור להשתמש תחת הקורה”, האיסור תלוי בחודה הפנימי היורד וסותם; ואילו במסגרת האוקימתא שבה מותר להשתמש תחת הקורה, רש״י בד״ה „ומאן דאמר ארבעה קסבר קורה” מסביר שהקורה משום מחיצה וחודה החיצון יורד וסותם. לכאורה בחלק השני של P02555 צ״ל „למ״ד מותר ... דחודה החיצון”, אך יש לוודא שגם המשך הניתוח — שתחת הקורה הוא כמקום המחיצה ולא כמקום הניתר — מתאים לתיקון זה. אין לתקן את גוף כתב־היד לפני בדיקת התאמת המודל כולו.\u003c/p>"}, {"id": "1066", "n": 37, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-269 | סוג: קטע חסר | מקור: 04_רשויות/רשויות - סוגיות - עותק 4.txt\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"ובזה יש לדקדק דאין גדר היכר דאיכא במיעוט הנמשך לתוך המבוי שווה לגדר היכר דאיכא במיעוט שתחת הקורה, דהא ודאי שעי...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>229 [רגיל] גדר האי מקום כמקום הקורה (ולא חלק ממקום המבוי)\u003c/p>"}, {"id": "433", "n": 38, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0863 | חישוב טפח וחומש – להפריד בין גובה הלכתי לקו ראייה | חומרה: גבוהה החישוב של תוספת אלכסון בגובה הקורה (טפח וחומש או טפח ושלושה חומשים) מניח שקו הראייה נמדד מן הקצה הפנימי של המיעוט אל שפת הקורה באלכסון. אולם שיעור „עשרים אמה” בסוגיה נמדד בגובה החלל באופן אנכי, ולא נאמר במפורש שהוא משתנה לפי קו הראייה האלכסוני של העומד על המיעוט. אם החישוב נועד לבחון את מנגנון ההיכר ולא את שיעור הגובה ההלכתי, יש לומר זאת ולצרף שרטוט עם נקודת הצופה, קו הראייה והמרחקים. אחרת עלול להיראות כאילו משנים את אופן מדידת שיעור עשרים עצמו.\u003c/p>"}, {"id": "1067", "n": 39, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-270 | סוג: קטע חסר | מקור: 04_רשויות/רשויות - סוגיות - עותק 4.txt\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"ולא פליגי אביי ורב יוסף אלא ביחס להיכר דהנ\"ל, היינו, קורה אחלל (ודחשיבא קורה במה שהיא קורה דחלל, בחלל שאינו יו...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>ועתה תראה דהיכר האמור בשימוש וכו', אינו בהיכר קורה כשלעצמה, אלא בהיכר הקורה ביחס למבוי,\u003c/p>\u003cp>.\u003c/p>"}]};
